<?php if($report):pur_text('Why Prior Approval Was Not Recorded','exception_reason','',true);pur_input('Actual Total Cost (GHS)','actual_cost');pur_input('Actual Delivery / Completion At (UTC)','delivered_at',gmdate('Y-m-d\TH:i:s'),'datetime-local');pur_text('Goods Received / Work Completed','description','',true);pur_select('Payment Status','payment_status',['unpaid'=>'Not Paid Yet','paid'=>'Already Paid']);?><div data-reported-payment><?php pur_select('Actual Payer','payer_id',array_column($options['payers'],'name','id'),(string)$actor);pur_input('Actual Payment At (UTC)','paid_at',gmdate('Y-m-d\TH:i:s'),'datetime-local');pur_input('Payment Reference','reference','',required:false);?></div><?php pur_upload('Receipt / Work Evidence');pur_text('Alternative Evidence If No Receipt','missing_evidence');pur_check('received','The complete goods or service described were received and checked.');?><p class="pu-note">This reports actual facts as an exception. It does not create retrospective prior approval. For previously received stock, identify the existing movement or count in the description/evidence. This cost-only route never adds inventory.</p>
